const AdmZip = require('adm-zip');
const path = require('path');
const files = [
  'testbed/docs/travel_summary.docx',
  'testbed/docs/report.docx',
  'testbed/docs/customer_report.docx',
  'testbed/docs/Meeting_Notes_2024_06.docx',
];
