const AdmZip = require('adm-zip');
const zip = new AdmZip('testbed/docs/travel_summary.docx');
let docXml = zip.readAsText('word/document.xml');

// Create a new paragraph with the note text
const note = 'Maya Chen\\'s Seattle travel records (Booking C4C633, Reservation HR-7D93, Rental CR-BE00) have been reviewed and are up to date as of this summary.';
const newParagraph = '<w:p><w:r><w:t>' + note + '</w:t></w:r></w:p>';

// Insert before the closing </w:body> tag
docXml = docXml.replace('</w:body>', newParagraph + '</w:body>');

// Update the entry and save
zip.updateFile('word/document.xml', Buffer.from(docXml, 'utf-8'));
zip.writeZip('testbed/docs/travel_summary.docx');
console.log('Note appended successfully.');
"

