const AdmZip = require('adm-zip');
const PDFDocument = require('pdfkit');
const fs = require('fs');

// Extract text from docx
const zip = new AdmZip('testbed/docs/travel_summary.docx');
const docXml = zip.readAsText('word/document.xml');
const lines = [];
const paragraphs = docXml.match(/<w:p[ >].*?<\/w:p>/gs) || [];
for (const p of paragraphs) {
  const texts = [];
  const runs = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
  for (const r of runs) {
    const m = r.match(/<w:t[^>]*>([^<]*)<\/w:t>/);
    if (m) texts.push(m[1]);
  }
  lines.push(texts.join(''));
}

// Build PDF
const doc = new PDFDocument({ size: 'A4', margins: { top: 50, bottom: 50, left: 50, right: 50 } });
const output = fs.createWriteStream('testbed/docs/travel_summary.pdf');
doc.pipe(output);

const title = 'Travel Booking Summary';
const sectionHeaders = ['Flights', 'Hotels', 'Car Rentals'];

for (const line of lines) {
  if (!line) {
    doc.moveDown(0.3);
    continue;
  }

  if (line === title) {
    doc.fontSize(18).font('Helvetica-Bold').text(line);
    doc.moveDown(0.8);
  } else if (sectionHeaders.includes(line)) {
    doc.moveDown(0.5);
    doc.fontSize(14).font('Helvetica-Bold').text(line);
    doc.moveDown(0.4);
  } else if (line.startsWith('Maya Chen') && line.includes('reviewed')) {
    // The appended note - style it distinctly
    doc.moveDown(0.6);
    doc.fontSize(10).font('Helvetica-BoldOblique').text(line);
  } else {
    doc.fontSize(9).font('Helvetica').text(line);
    doc.moveDown(0.15);
  }
}

doc.end();

output.on('finish', () => {
  const stats = fs.statSync('testbed/docs/travel_summary.pdf');
  console.log('PDF created: testbed/docs/travel_summary.pdf (' + (stats.size / 1024).toFixed(1) + ' KB)');
});
"

